import os
import json

brain = r"C:\Users\Lin\.gemini\antigravity\brain"
for root, dirs, files in os.walk(brain):
    for f in files:
        if f == "transcript_full.jsonl":
            p = os.path.join(root, f)
            conv = os.path.basename(os.path.dirname(os.path.dirname(p)))
            try:
                with open(p, "r", encoding="utf-8", errors="ignore") as fl:
                    for line in fl:
                        if "spawn_lightning_strike_vfx" in line and ("edit_file" in line or "write_file" in line):
                            data = json.loads(line)
                            for tc in data.get("tool_calls", []):
                                if "spawn_lightning_strike_vfx" in str(tc):
                                    print("Conv:", conv, "Step:", data["step_index"], tc["name"])
                                    with open(f"scratch/{conv}_{data['step_index']}_lightning.json", "w", encoding="utf-8") as out:
                                        json.dump(tc, out)
            except Exception:
                pass
